//! The matplotlib colour map library, as rio-tiler (and GeoLibre) lists it: matplotlib's own
//! maps, cmocean's and rio-tiler's cfastie, rplumbo and schwarzwald. Generated from rio-tiler's
//! 256-colour tables, each reduced to the fewest stops that reproduce it within 2 levels per
//! channel (qualitative maps keep their colours as they are). Viridis, Plasma, Inferno, Magma,
//! Cividis, Turbo, Haline, Balance, Deep, Topo and Greys are our own ramps already and are not
//! repeated here. Their sources and licences are in `ATTRIBUTION.md`.

use super::RampKind;

const fn h(c: u32) -> [u8; 3] {
    [(c >> 16) as u8, (c >> 8) as u8, c as u8]
}

/// A colour map: its name, its kind and its stops, each a position in 0..=255 and a colour.
pub(super) struct Colormap {
    pub name: &'static str,
    pub kind: RampKind,
    pub stops: &'static [(u8, [u8; 3])],
}

